def is_session_expired(created_at: 'datetime', ttl_seconds: int, current_time: 'datetime') -> bool:
    """Buggy: uses timedelta.seconds which discards day component."""
    from datetime import datetime

    if not isinstance(created_at, datetime) or not isinstance(current_time, datetime):
        raise TypeError("created_at and current_time must be datetime")
    if not isinstance(ttl_seconds, int):
        raise TypeError("ttl_seconds must be int")
    if ttl_seconds < 0:
        raise ValueError("ttl_seconds must be non-negative")

    delta = current_time - created_at

    # BUG: .seconds is modulo 24 hours; sessions older than a day will be wrong.
    age_seconds = int(delta.seconds)

    return age_seconds >= ttl_seconds

def is_session_expired(created_at: 'datetime', ttl_seconds: int, current_time: 'datetime') -> bool:
    """Buggy: treats ttl_seconds <= 0 as never expiring, and doesn't validate negative TTL."""
    from datetime import datetime, timedelta

    if not isinstance(created_at, datetime) or not isinstance(current_time, datetime):
        raise TypeError("created_at and current_time must be datetime")
    if not isinstance(ttl_seconds, int):
        raise TypeError("ttl_seconds must be int")

    # BUG: ttl_seconds == 0 should expire immediately; negative should raise.
    if ttl_seconds <= 0:
        return False

    expires_at = created_at + timedelta(seconds=ttl_seconds)
    if current_time < created_at:
        return False

    return current_time >= expires_at
